class Book:
    def __init__(self, title, author, year):
        self._title = title
        self._author = author
        self._year = year
        self._available = True

    @property
    def title(self):
        return self._title

    @property
    def author(self):
        return self._author

    @property
    def year(self):
        return self._year

    @property
    def available(self):
        return self._available

    def is_available(self):
        return self._available

    def __str__(self):
        return f'{self._title} by {self._author} ({self._year})'

    def borrow(self):
        if self._available:
            self._available = False
            return True
        return False

b = Book('1984', 'Orwell', 1949)
print(b.is_available())
print(b)
print(b.borrow())
print(b.is_available())

