class BankAccount:
    def __init__(self, owner_name, account_number, balance=0):
        self.owner_name = owner_name
        self.account_number = account_number
        self.__balance = balance

    def __add__(self, other):
        if isinstance(other, BankAccount):
            new_balance = self.__balance + other.__balance
            return BankAccount(self.owner_name + ' & ' + other.owner_name, 'COMBINED', new_balance)
        return NotImplemented

    def __str__(self):
        return 'BankAccount(owner=' + self.owner_name + ', balance=' + str(self.__balance) + ')'

    def get_balance(self):
        return self.__balance

    def display_balance(self):
        print(self)

acc1 = BankAccount('Alice', '001', 300)
acc2 = BankAccount('Bob', '002', 400)
result = acc1 + acc2
print(result)
print('Combined balance:', result.get_balance())
